"""Prep list generator for small restaurants (prototype).
Input: menu items with par levels and current counts. Output: what to prep today."""
import json, sys

def prep_list(items):
    out = []
    for it in items:
        need = it["par"] - it["on_hand"]
        if need > 0:
            out.append((it["name"], need, it["unit"]))
    return out

if __name__ == "__main__":
    data = json.load(open(sys.argv[1])) if len(sys.argv) > 1 else []
    for name, need, unit in prep_list(data):
        print(f"{name}: prep {need} {unit}")
